/*
 * ポリゴンモデルのサンプル
 * 座標系：右手系．右が +x，上が +y，手前が +z．
 * コンパイル：cc sample.c -lpolygon -L. -o sample
 * キー操作：[↑], [↓], [←], [→], [Space]，[B]，[R]，[Q]
 */

#include "polygon.h"

void shader(Polygon *p)
{
  double s;

  s = p->normal.vector[2];
  if (s <= 0.0)
  {
    p->shade = 0.2;

    p->visible = 0;
  }
  else
  {
    p->shade = s * 0.6 + 0.4;
    p->visible = 1;
  }
}

